package database

import (
	"context"
	"crypto/sha256"
	"fmt"
	"io/fs"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"time"

	"github.com/hkjang/igame/migrations"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
	"golang.org/x/crypto/bcrypt"
)

func Open(ctx context.Context, dsn string) (*pgxpool.Pool, error) {
	config, err := pgxpool.ParseConfig(dsn)
	if err != nil {
		return nil, fmt.Errorf("parse postgres DSN: %w", err)
	}
	config.MaxConns = 20
	config.MinConns = 2
	config.MaxConnLifetime = 30 * time.Minute
	config.MaxConnIdleTime = 5 * time.Minute
	pool, err := pgxpool.NewWithConfig(ctx, config)
	if err != nil {
		return nil, fmt.Errorf("open postgres: %w", err)
	}
	if err := pool.Ping(ctx); err != nil {
		pool.Close()
		return nil, fmt.Errorf("ping postgres: %w", err)
	}
	return pool, nil
}

// migrationFileName is the convention every schema migration follows: a
// zero-padded number, an underscore, a lower-case name, then ".sql".
var migrationFileName = regexp.MustCompile(`^([0-9]+)_[a-z0-9_]+\.sql$`)

// migrationNames lists the schema migrations in the order they must be applied.
//
// The files are ordered by their number rather than by their name. Sorting the
// names agrees with the numbers only while every number is padded to the same
// width, so the moment a "10_x.sql" joined the existing "001_".."009_" it would
// sort second and try to alter tables that do not exist yet — against a live
// database, halfway through a deployment. Sorting on the parsed number instead
// keeps the order the numbers describe no matter how they are written.
//
// A name that does not follow the convention, or a number used twice, is
// refused rather than applied at a guessed position: the files are compiled in,
// so this is a mistake in the repository that every start-up should report the
// same way instead of one that depends on the file system.
func migrationNames(fsys fs.FS) ([]string, error) {
	entries, err := fs.ReadDir(fsys, ".")
	if err != nil {
		return nil, err
	}
	type migration struct {
		number int
		name   string
	}
	found := make([]migration, 0, len(entries))
	seen := make(map[int]string, len(entries))
	for _, entry := range entries {
		name := entry.Name()
		if entry.IsDir() || !strings.HasSuffix(name, ".sql") {
			continue
		}
		match := migrationFileName.FindStringSubmatch(name)
		if match == nil {
			return nil, fmt.Errorf("migration %s is not named <number>_<name>.sql", name)
		}
		number, err := strconv.Atoi(match[1])
		if err != nil {
			return nil, fmt.Errorf("migration %s has an unreadable number: %w", name, err)
		}
		if other, duplicate := seen[number]; duplicate {
			return nil, fmt.Errorf("migrations %s and %s share the number %d", other, name, number)
		}
		seen[number] = name
		found = append(found, migration{number: number, name: name})
	}
	sort.Slice(found, func(i, j int) bool { return found[i].number < found[j].number })
	names := make([]string, 0, len(found))
	for _, entry := range found {
		names = append(names, entry.name)
	}
	return names, nil
}

func Migrate(ctx context.Context, pool *pgxpool.Pool) error {
	if _, err := pool.Exec(ctx, `CREATE TABLE IF NOT EXISTS schema_migrations (
		name text PRIMARY KEY, checksum text NOT NULL, applied_at timestamptz NOT NULL DEFAULT now())`); err != nil {
		return fmt.Errorf("create schema migrations table: %w", err)
	}
	names, err := migrationNames(migrations.Files)
	if err != nil {
		return err
	}
	for _, name := range names {
		body, err := migrations.Files.ReadFile(name)
		if err != nil {
			return err
		}
		checksum := fmt.Sprintf("%x", sha256.Sum256(body))
		var existing string
		err = pool.QueryRow(ctx, `SELECT checksum FROM schema_migrations WHERE name=$1`, name).Scan(&existing)
		if err == nil {
			if existing != checksum {
				return fmt.Errorf("migration %s checksum changed", name)
			}
			continue
		}
		if err != pgx.ErrNoRows {
			return fmt.Errorf("read migration %s state: %w", name, err)
		}
		tx, err := pool.Begin(ctx)
		if err != nil {
			return err
		}
		if _, err = tx.Exec(ctx, string(body)); err == nil {
			_, err = tx.Exec(ctx, `INSERT INTO schema_migrations(name,checksum) VALUES($1,$2)`, name, checksum)
		}
		if err != nil {
			_ = tx.Rollback(ctx)
			return fmt.Errorf("apply migration %s: %w", name, err)
		}
		if err := tx.Commit(ctx); err != nil {
			return fmt.Errorf("commit migration %s: %w", name, err)
		}
	}
	return nil
}

// EnsureBootstrapAdmin creates the first local administrator. It intentionally
// does not overwrite a password later changed through the administrator UI.
func EnsureBootstrapAdmin(ctx context.Context, pool *pgxpool.Pool, username, password string) error {
	hash, err := bcrypt.GenerateFromPassword([]byte(password), bcrypt.DefaultCost)
	if err != nil {
		return err
	}
	_, err = pool.Exec(ctx, `INSERT INTO users(username,display_name,password_hash,role,status)
		VALUES($1,$1,$2,'admin','active') ON CONFLICT(username) DO UPDATE SET
		password_hash=CASE WHEN users.password_hash='' THEN excluded.password_hash ELSE users.password_hash END,
		role='admin',status='active',updated_at=now()`, username, string(hash))
	if err != nil {
		return fmt.Errorf("ensure bootstrap administrator: %w", err)
	}
	return nil
}
package main

import (
	"context"
	"errors"
	"fmt"
	"io"
	"log/slog"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"
	_ "time/tzdata"

	"github.com/hkjang/igame/internal/api"
	"github.com/hkjang/igame/internal/config"
	"github.com/hkjang/igame/internal/database"
	"github.com/hkjang/igame/internal/secretbox"
	"github.com/hkjang/igame/internal/version"
	"github.com/jackc/pgx/v5/pgxpool"
)

const healthcheckURL = "http://127.0.0.1:8080/healthz"

func main() {
	log := slog.New(slog.NewJSONHandler(os.Stdout, &slog.HandlerOptions{Level: slog.LevelInfo}))
	if len(os.Args) == 2 && os.Args[1] == "healthcheck" {
		ctx, cancel := context.WithTimeout(context.Background(), 4*time.Second)
		defer cancel()
		if err := checkHealth(ctx, healthcheckURL); err != nil {
			log.Error("healthcheck failed", "error", err)
			os.Exit(1)
		}
		return
	}
	cfg, err := config.Load()
	if err != nil {
		log.Error("configuration error", "error", err)
		os.Exit(1)
	}
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	db, err := database.Open(ctx, cfg.PostgresDSN)
	if err == nil {
		err = database.Migrate(ctx, db)
	}
	if err == nil {
		err = database.EnsureBootstrapAdmin(ctx, db, cfg.BootstrapAdmin, cfg.BootstrapPassword)
	}
	cancel()
	if err != nil {
		log.Error("startup failed", "error", err)
		if db != nil {
			db.Close()
		}
		os.Exit(1)
	}
	defer db.Close()
	box, err := secretbox.New(cfg.EncryptionKey)
	if err != nil {
		log.Error("encryption initialization failed", "error", err)
		os.Exit(1)
	}
	service := api.New(db, box, log)
	server := &http.Server{Addr: ":8080", Handler: service.Router(), ReadHeaderTimeout: 10 * time.Second, ReadTimeout: 30 * time.Second, WriteTimeout: 0, IdleTimeout: 2 * time.Minute, MaxHeaderBytes: 1 << 20}
	// Idle stream clients must not hold a graceful shutdown open for the whole
	// shutdown timeout.
	server.RegisterOnShutdown(service.Drain)
	cleanupCtx, cleanupCancel := context.WithCancel(context.Background())
	defer cleanupCancel()
	go cleanupExpired(cleanupCtx, db, log)
	go func() {
		log.Info("igame started", "address", server.Addr, "version", version.Version, "commit", version.Commit)
		if err := server.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
			log.Error("HTTP server failed", "error", err)
			os.Exit(1)
		}
	}()
	stop := make(chan os.Signal, 1)
	signal.Notify(stop, syscall.SIGINT, syscall.SIGTERM)
	<-stop
	cleanupCancel()
	shutdownCtx, shutdownCancel := context.WithTimeout(context.Background(), 20*time.Second)
	defer shutdownCancel()
	if err := server.Shutdown(shutdownCtx); err != nil {
		log.Error("graceful shutdown failed", "error", err)
	}
}

// checkHealth is used by the package-free runtime image. It deliberately runs
// before application configuration and database initialization so Docker can
// probe an already-running container without a shell or utility binary.
func checkHealth(ctx context.Context, endpoint string) error {
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, endpoint, nil)
	if err != nil {
		return fmt.Errorf("create health request: %w", err)
	}
	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		return fmt.Errorf("request health endpoint: %w", err)
	}
	defer resp.Body.Close()
	_, _ = io.Copy(io.Discard, io.LimitReader(resp.Body, 4<<10))
	if resp.StatusCode < http.StatusOK || resp.StatusCode >= http.StatusMultipleChoices {
		return fmt.Errorf("health endpoint returned %s", resp.Status)
	}
	return nil
}

// cleanupExpired keeps all background state in PostgreSQL and introduces no
// additional runtime setting.
func cleanupExpired(ctx context.Context, db *pgxpool.Pool, log *slog.Logger) {
	ticker := time.NewTicker(time.Hour)
	defer ticker.Stop()
	// Run once at startup so a restart also clears whatever expired while the
	// service was down, instead of waiting a full hour for the first tick.
	cleanupOnce(ctx, db, log)
	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			cleanupOnce(ctx, db, log)
		}
	}
}

func cleanupOnce(ctx context.Context, db *pgxpool.Pool, log *slog.Logger) {
	ctx, cancel := context.WithTimeout(ctx, time.Minute)
	defer cancel()
	_, sessionErr := db.Exec(ctx, `DELETE FROM auth_sessions WHERE expires_at<now()`)
	_, flowErr := db.Exec(ctx, `DELETE FROM oidc_flows WHERE expires_at<now()`)
	_, gameErr := db.Exec(ctx, `UPDATE game_sessions SET status='abandoned',ended_at=now(),duration_ms=GREATEST(0,extract(epoch FROM(now()-started_at))*1000)::bigint WHERE status='active' AND started_at<now()-interval '24 hours'`)
	if sessionErr != nil || flowErr != nil || gameErr != nil {
		log.Warn("expired state cleanup failed", "session_error", sessionErr, "flow_error", flowErr, "game_session_error", gameErr)
	}
}

